E=pathlib.Path(__file__).parent
script='set -eu\numask 077\nf=$(mktemp)\ntrap \'rm -f "$f"\' EXIT\nprintf \'[client]\\nuser=root\\npassword=%s\\n\' "$MARIADB_ROOT_PASSWORD" > "$f"\nmariadb-dump --defaults-extra-file="$f" --single-transaction --routines --triggers elitesync_v10_1_2_dev\n'
r=subprocess.run(['docker','exec','-i','elitesync-v1012-journey-db','sh'],input=script.encode(),capture_output=True);(E/'after-r1.private.sql').write_bytes(r.stdout);(E/'backup-after-r1.stderr').write_bytes(r.stderr);assert r.returncode==0 and len(r.stdout)>400000
