(E/'resource-final.json').write_text(json.dumps({'owned_db':'stopped','volume_retained':vol,'owned_api':'stopped','authorized_AVD':'stopped','adb_reverse_8015':'removed','phone':'NOT_OPERATED','WS':'NOT_STARTED','RTC_UDP_firewall_DNAT_UAC_cloud':'NOT_RUN','docker_engine':'left running; no global shutdown','before_backup_sha256':hashlib.sha256((E/'before-r1.private.sql').read_bytes()).hexdigest(),'after_backup_sha256':hashlib.sha256((E/'after-r1.private.sql').read_bytes()).hexdigest()},indent=2));print('owned API/DB/AVD stopped; volume and both backups retained; reverse removed')
